let farmCameraZoom=null;
const farmSceneMap=farmMap;
farmMap=function(){const n=cityPlots().length,width=Math.max(760,Math.min(1500,Math.ceil(Math.sqrt(n+1))*235));return `<div class="farm-camera-controls"><span>Всё хозяйство · ${n} грядок</span><div><button class="btn light" onclick="adjustFarmCamera(-.15)" aria-label="Отдалить карту">−</button><button class="btn light" onclick="farmCameraZoom=null;fitFarmCamera()">Вместить всё</button><button class="btn light" onclick="adjustFarmCamera(.15)" aria-label="Приблизить карту">＋</button></div></div><div class="farm-camera-viewport" tabindex="0" aria-label="Карта хозяйства. Масштаб можно изменить кнопками"><div class="farm-camera-scene" style="width:${width}px">${farmSceneMap()}</div></div><p class="note">Карта уменьшается автоматически, чтобы показать всё хозяйство. Приблизьте для деталей или откройте «Список».</p>`};
function fitFarmCamera(){const viewport=document.querySelector('.farm-camera-viewport'),scene=document.querySelector('.farm-camera-scene');if(!viewport||!scene)return;const box=getComputedStyle(viewport);const usableWidth=viewport.clientWidth-parseFloat(box.paddingLeft)-parseFloat(box.paddingRight);const usableHeight=viewport.clientHeight-parseFloat(box.paddingTop)-parseFloat(box.paddingBottom);const automatic=Math.min(1,(usableWidth-8)/scene.offsetWidth,(usableHeight-8)/scene.offsetHeight);const scale=farmCameraZoom??automatic;scene.style.zoom=String(Math.max(.12,Math.min(1.6,scale)));viewport.dataset.scale=String(scale)}
function adjustFarmCamera(delta){const v=document.querySelector('.farm-camera-viewport');farmCameraZoom=Math.max(.15,Math.min(1.6,Number(v?.dataset.scale||1)+delta));fitFarmCamera()}
let farmCameraObserver;
const beforeCameraRender=render;render=function(){beforeCameraRender();farmCameraObserver?.disconnect();const viewport=document.querySelector('.farm-camera-viewport');if(viewport){fitFarmCamera();farmCameraObserver=new ResizeObserver(fitFarmCamera);farmCameraObserver.observe(viewport)}};
addEventListener('hashchange',()=>{farmCameraZoom=null;fitFarmCamera()});render();
